import { useCallback, useEffect, useRef, useState } from "react";
import { ChevronRight, Columns2, FolderOpen, Plus, Rows2, X } from "lucide-react";
// @ts-ignore wailsjs bindings are generated by wails build
import { StartPty, StopPty } from "../../wailsjs/go/controllers/Terminal";
// @ts-ignore wailsjs bindings are generated by wails build
import { CloseSSHShell, ListHosts, OpenSSHShell } from "../../wailsjs/go/controllers/SSH";
// @ts-ignore wailsjs bindings are generated by wails build
import { ListProjects } from "../../wailsjs/go/controllers/Projects";
// @ts-ignore wailsjs bindings are generated by wails build
import { GetTerminalWorkspace, SaveTerminalWorkspace } from "../../wailsjs/go/controllers/Terminal";
import RemoteTerminal from "../components/terminal/RemoteTerminal";
import Terminal from "../components/terminal/Terminal";
import WorkspaceNavigator from "../components/workspace/WorkspaceNavigator";
import { useT } from "../lib/i18n";

// --- split tree model --------------------------------------------------------

type Pane = {
  id: string; // PTY session id (local) or SSH shell id
  kind: string; // "powershell" | "cmd" | "gitbash" | "ssh"
  project?: string;
  // host names the saved SSH target for kind === "ssh".
  host?: string;
};

type SplitDir = "h" | "v";

type Node =
  | { type: "leaf"; pane: Pane }
  | { type: "split"; dir: SplitDir; children: Node[] };

type Tab = {
  id: string;
  root: Node;
  label: string;
};

// --- tree helpers ------------------------------------------------------------

function findLeaf(node: Node, paneId: string): Node | null {
  if (node.type === "leaf") return node.pane.id === paneId ? node : null;
  for (const child of node.children) {
    const found = findLeaf(child, paneId);
    if (found) return found;
  }
  return null;
}

function mapNode(node: Node, fn: (n: Node) => Node): Node {
  const mapped = fn(node);
  if (mapped.type === "split") {
    return { ...mapped, children: mapped.children.map((c) => mapNode(c, fn)) };
  }
  return mapped;
}

function removeLeaf(node: Node, paneId: string): Node | null {
  if (node.type === "leaf") return node.pane.id === paneId ? null : node;
  const kept = node.children
    .map((c) => removeLeaf(c, paneId))
    .filter((n): n is Node => n !== null);
  if (kept.length === 0) return null;
  if (kept.length === 1) return kept[0];
  return { ...node, children: kept };
}

function splitLeafAt(node: Node, paneId: string, dir: SplitDir, newPane: Pane): Node {
  if (node.type === "leaf" && node.pane.id === paneId) {
    return {
      type: "split",
      dir,
      children: [
        { type: "leaf", pane: node.pane },
        { type: "leaf", pane: newPane },
      ],
    };
  }
  if (node.type === "split") {
    return {
      ...node,
      children: node.children.map((c) => splitLeafAt(c, paneId, dir, newPane)),
    };
  }
  return node;
}

function collectPanes(node: Node): Pane[] {
  if (node.type === "leaf") return [node.pane];
  return node.children.flatMap(collectPanes);
}

// --- component ----------------------------------------------------------------

let nextTabId = 0;
let nextPaneLabel = 0;

export default function TerminalPage() {
  const t = useT();
  const [tabs, setTabs] = useState<Tab[]>([]);
  const [activeTab, setActiveTab] = useState(0);
  const [projects, setProjects] = useState<string[]>([]);
  const [kind, setKind] = useState("powershell");
  const [sshHosts, setSshHosts] = useState<string[]>([]);
  const [showNavigator, setShowNavigator] = useState(true);
  const [projectName, setProjectName] = useState("");
  const restored = useRef(false);

  useEffect(() => {
    ListProjects().then((list: Array<{ name: string }>) => {
      setProjects((list ?? []).map((p) => p.name));
    }).catch(() => { /* pre-startup */ });
    ListHosts().then((list: Array<{ name: string }>) => {
      setSshHosts((list ?? []).map((h) => h.name));
    }).catch(() => { /* no hosts yet */ });
  }, []);

  const spawnPane = useCallback(
    async (project?: string): Promise<Pane | null> => {
      try {
        const sessionId = await StartPty({ kind, project: project || "", cols: 80, rows: 24 });
        nextPaneLabel++;
        return { id: sessionId, kind, project };
      } catch {
        return null;
      }
    },
    [kind],
  );

  // spawnSSHPane opens a remote shell pane for a saved SSH host.
  const spawnSSHPane = useCallback(async (host: string): Promise<Pane | null> => {
    try {
      const shellId = await OpenSSHShell(host, 80, 24);
      return { id: shellId, kind: "ssh", host };
    } catch {
      return null;
    }
  }, []);

  const openNewTab = useCallback(
    async (project?: string) => {
      const pane = await spawnPane(project);
      if (!pane) return;
      const tab: Tab = {
        id: `tab-${nextTabId++}`,
        root: { type: "leaf", pane },
        label: project ?? kind,
      };
      setTabs((current) => {
        setActiveTab(current.length);
        return [...current, tab];
      });
    },
    [spawnPane, kind],
  );

  const splitCurrent = useCallback(
    async (dir: SplitDir) => {
      const tab = tabs[activeTab];
      if (!tab) return;
      // Split the last leaf (rightmost/bottom pane).
      const panes = collectPanes(tab.root);
      const target = panes[panes.length - 1];
      if (!target) return;
      const newPane = await spawnPane();
      if (!newPane) return;
      setTabs((current) =>
        current.map((tb, i) =>
          i === activeTab ? { ...tb, root: splitLeafAt(tb.root, target.id, dir, newPane) } : tb,
        ),
      );
    },
    [tabs, activeTab, spawnPane],
  );

  const closePane = useCallback(
    (tabIdx: number, pane: Pane) => {
      if (pane.kind === "ssh") CloseSSHShell(pane.id).catch(() => { /* dead */ });
      else StopPty(pane.id).catch(() => { /* dead */ });
      setTabs((current) => {
        const tab = current[tabIdx];
        if (!tab) return current;
        const newRoot = removeLeaf(tab.root, pane.id);
        if (newRoot === null) {
          const next = current.filter((_, i) => i !== tabIdx);
          setActiveTab(Math.max(0, tabIdx - 1));
          return next;
        }
        return current.map((tb, i) => (i === tabIdx ? { ...tb, root: newRoot } : tb));
      });
    },
    [],
  );

  // openSSHTab opens a tab whose single pane is a remote shell.
  const openSSHTab = useCallback(
    async (host: string) => {
      const pane = await spawnSSHPane(host);
      if (!pane) return;
      const tab: Tab = { id: `tab-${nextTabId++}`, root: { type: "leaf", pane }, label: "ssh:" + host };
      setTabs((current) => {
        setActiveTab(current.length);
        return [...current, tab];
      });
    },
    [spawnSSHPane],
  );

  // Restore persisted layout on mount.
  useEffect(() => {
    if (restored.current) return;
    restored.current = true;
    (async () => {
      try {
        const raw = await GetTerminalWorkspace();
        if (!raw) return;
        const data = typeof raw === "string" ? JSON.parse(raw) : raw;
        if (!data?.tabs?.length) return;
        // Respawn each saved pane.
        for (const savedTab of data.tabs) {
          const panes: Pane[] = [];
          const walk = async (node: any) => {
            if (node?.type === "leaf") {
              const pane =
                node.pane?.kind === "ssh" && node.pane?.host
                  ? await spawnSSHPane(node.pane.host)
                  : await spawnPane(node.pane?.project || undefined);
              if (pane) panes.push(pane);
            } else if (node?.children) {
              for (const c of node.children) await walk(c);
            }
          };
          await walk(savedTab.root);
          if (panes.length === 0) continue;
          // Rebuild the tree with new pane IDs, mapping old → new.
          let pi = 0;
          const remap = (node: any): Node => {
            if (node?.type === "leaf") {
              return { type: "leaf", pane: panes[pi++] ?? panes[0] };
            }
            return { type: "split", dir: node?.dir ?? "h", children: (node?.children ?? []).map(remap) };
          };
          const tab: Tab = {
            id: `tab-${nextTabId++}`,
            root: remap(savedTab.root),
            label: savedTab.label ?? "terminal",
          };
          setTabs((current) => [...current, tab]);
        }
      } catch { /* no saved layout */ }
    })();
  }, [spawnPane, spawnSSHPane]);

  // Persist layout on change (debounced).
  const persistTimer = useRef<number | null>(null);
  useEffect(() => {
    if (persistTimer.current) window.clearTimeout(persistTimer.current);
    persistTimer.current = window.setTimeout(() => {
      const data = {
        version: 1,
        tabs: tabs.map((tb) => ({
          label: tb.label,
          root: tb.root,
        })),
      };
      SaveTerminalWorkspace(JSON.stringify(data)).catch(() => { /* pre-startup */ });
    }, 500);
    return () => {
      if (persistTimer.current) window.clearTimeout(persistTimer.current);
    };
  }, [tabs]);

  // Auto-open first tab if none after restore.
  useEffect(() => {
    if (tabs.length === 0 && restored.current) {
      const timer = setTimeout(() => void openNewTab(), 300);
      return () => clearTimeout(timer);
    }
  }, [tabs.length, restored, openNewTab]);

  // Ctrl+T new tab, Ctrl+W close last pane of active tab.
  useEffect(() => {
    const onKey = (event: KeyboardEvent) => {
      if (!event.ctrlKey) return;
      if (event.key === "t") {
        event.preventDefault();
        void openNewTab();
      } else if (event.key === "w") {
        event.preventDefault();
        const tab = tabs[activeTab];
        if (tab) {
          const panes = collectPanes(tab.root);
          if (panes.length > 0) closePane(activeTab, panes[panes.length - 1]);
        }
      }
    };
    window.addEventListener("keydown", onKey, true);
    return () => window.removeEventListener("keydown", onKey, true);
  }, [tabs, activeTab, openNewTab, closePane]);

  const tab = tabs[activeTab];

  return (
    <div className="flex h-full flex-col gap-1.5">
      {/* Toolbar */}
      <div className="flex items-center gap-2 px-1 text-xs">
        <select className="input py-0.5 text-xs" value={kind} onChange={(e) => setKind(e.target.value)} aria-label="Shell">
          <option value="powershell">PowerShell</option>
          <option value="cmd">CMD</option>
          <option value="gitbash">Git Bash</option>
        </select>
        <select
          className="input py-0.5 text-xs"
          value=""
          onChange={(e) => e.target.value && void openNewTab(e.target.value)}
          aria-label="Project"
        >
          <option value="">{t("terminal.newTab")}</option>
          {projects.map((name) => (
            <option key={name} value={name}>{name}</option>
          ))}
        </select>
        {sshHosts.length > 0 && (
          <select
            className="input py-0.5 text-xs"
            value=""
            onChange={(e) => e.target.value && void openSSHTab(e.target.value)}
            aria-label="SSH host"
          >
            <option value="">{t("terminal.sshTab")}</option>
            {sshHosts.map((name) => (
              <option key={name} value={name}>ssh:{name}</option>
            ))}
          </select>
        )}
        <button
          type="button"
          onClick={() => setShowNavigator(!showNavigator)}
          title={showNavigator ? "Hide navigator" : "Show navigator"}
          className={`flex items-center gap-1 rounded border px-2 py-1 ${
            showNavigator ? "border-accent/40 bg-accent/15 text-accent2" : "border-white/10 bg-white/5 text-white/50 hover:bg-white/10"
          }`}
        >
          <FolderOpen className="h-3 w-3" />
        </button>
        {showNavigator && (
          <select
            className="input py-0.5 text-xs"
            value={projectName}
            onChange={(e) => setProjectName(e.target.value)}
            aria-label="Navigator project"
          >
            <option value="">—</option>
            {projects.map((name) => (
              <option key={name} value={name}>{name}</option>
            ))}
          </select>
        )}
        <button
          type="button"
          onClick={() => void openNewTab()}
          title="Ctrl+T"
          className="flex items-center gap-1 rounded border border-white/10 bg-white/5 px-2 py-1 text-white/70 hover:bg-white/10"
        >
          <Plus className="h-3 w-3" /> {t("terminal.tab")}
        </button>
        <button
          type="button"
          onClick={() => void splitCurrent("h")}
          title={t("terminal.splitH")}
          className="flex items-center gap-1 rounded border border-white/10 bg-white/5 px-2 py-1 text-white/70 hover:bg-white/10"
        >
          <Columns2 className="h-3 w-3" /> H
        </button>
        <button
          type="button"
          onClick={() => void splitCurrent("v")}
          title={t("terminal.splitV")}
          className="flex items-center gap-1 rounded border border-white/10 bg-white/5 px-2 py-1 text-white/70 hover:bg-white/10"
        >
          <Rows2 className="h-3 w-3" /> V
        </button>
      </div>

      {/* Tab strip */}
      <div className="flex items-center gap-0.5 overflow-x-auto border-b border-white/10 pb-1">
        {tabs.map((tb, i) => {
          const panes = collectPanes(tb.root);
          return (
            <button
              key={tb.id}
              type="button"
              onClick={() => setActiveTab(i)}
              className={`group flex items-center gap-1.5 rounded-t px-3 py-1.5 text-xs whitespace-nowrap ${
                i === activeTab ? "bg-white/10 text-white" : "text-white/50 hover:bg-white/5"
              }`}
            >
              <ChevronRight className="h-2.5 w-2.5 opacity-40" />
              {tb.label}
              {panes.length > 1 && <span className="text-[9px] text-white/30">×{panes.length}</span>}
              <span
                role="button"
                tabIndex={-1}
                onClick={(e) => {
                  e.stopPropagation();
                  panes.forEach((p) => closePane(i, p));
                }}
                className="ml-1 rounded p-0.5 opacity-0 group-hover:opacity-60 hover:bg-white/20 hover:opacity-100"
              >
                <X className="h-3 w-3" />
              </span>
            </button>
          );
        })}
      </div>

      {/* Terminal area: workspace navigator + recursive split tree */}
      <div className="flex min-h-0 flex-1 gap-1">
        {/* Navigator sidebar */}
        {showNavigator && projectName && (
          <div className="w-[280px] shrink-0 overflow-hidden rounded-lg border border-white/10 bg-black/20">
            <WorkspaceNavigator projectName={projectName} />
          </div>
        )}

        {/* Terminal split tree */}
        <div className="min-h-0 min-w-0 flex-1 overflow-hidden rounded-lg border border-white/10 bg-[#171717]">
          {tab && <SplitView node={tab.root} tabIdx={activeTab} onClose={closePane} />}
        </div>
      </div>
    </div>
  );
}

// --- recursive split renderer ---------------------------------------------------

function SplitView({ node, tabIdx, onClose }: { node: Node; tabIdx: number; onClose: (tabIdx: number, pane: Pane) => void }) {
  if (node.type === "leaf") {
    const body =
      node.pane.kind === "ssh" ? (
        <RemoteTerminal shellId={node.pane.id} onExit={() => onClose(tabIdx, node.pane)} />
      ) : (
        <Terminal sessionId={node.pane.id} onExit={() => onClose(tabIdx, node.pane)} />
      );
    return (
      <div className="group relative h-full min-w-0 min-h-0">
        {body}
        <button
          type="button"
          onClick={() => onClose(tabIdx, node.pane)}
          className="absolute right-1.5 top-1.5 z-10 rounded border border-white/20 bg-black/60 p-0.5 text-white/60 opacity-0 transition-opacity group-hover:opacity-100 hover:text-white"
        >
          <X className="h-2.5 w-2.5" />
        </button>
      </div>
    );
  }
  const isHorizontal = node.dir === "h";
  return (
    <div className={`flex h-full min-h-0 min-w-0 ${isHorizontal ? "flex-row" : "flex-col"}`}>
      {node.children.map((child, i) => (
        <div
          key={i}
          className={`min-w-0 min-h-0 flex-1 ${
            i > 0 ? (isHorizontal ? "border-l border-white/10" : "border-t border-white/10") : ""
          }`}
        >
          <SplitView node={child} tabIdx={tabIdx} onClose={onClose} />
        </div>
      ))}
    </div>
  );
}
